#!/usr/bin/env node
// actualizar-landing.mjs
// Reemplaza la landing de ARCREDIX por la nueva (segun la especificacion de marca)
// y unifica los colores del resto de la app con la paleta oficial.
//
// Uso (desde la raiz del proyecto arcredix, donde esta package.json):
//   node actualizar-landing.mjs

import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
if (!fs.existsSync(path.join(root, "package.json")) || !fs.existsSync(path.join(root, "lib", "plans.ts"))) {
  console.error("Ejecuta este script en la raiz del proyecto ARCREDIX (donde estan package.json y la carpeta lib).");
  process.exit(1);
}

const TEXT_FILES = {
 "components/landing/QrArt.tsx": "// QR ilustrativo (no es un código real): patrón fijo para que servidor y cliente coincidan\nfunction rng(seed: number) {\n  let s = seed;\n  return () => (s = (s * 1664525 + 1013904223) % 4294967296) / 4294967296;\n}\n\nexport function QrArt({ size = 96 }: { size?: number }) {\n  const n = 21;\n  const r = rng(7);\n  const inFinder = (x: number, y: number) =>\n    (x < 8 && y < 8) || (x > n - 9 && y < 8) || (x < 8 && y > n - 9);\n  const cells: [number, number][] = [];\n  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (!inFinder(x, y) && r() > 0.52) cells.push([x, y]);\n  const finder = (x: number, y: number) => (\n    <g key={`${x}-${y}`}>\n      <rect x={x} y={y} width=\"7\" height=\"7\" fill=\"#050B12\" />\n      <rect x={x + 1} y={y + 1} width=\"5\" height=\"5\" fill=\"#fff\" />\n      <rect x={x + 2} y={y + 2} width=\"3\" height=\"3\" fill=\"#050B12\" />\n    </g>\n  );\n  return (\n    <svg viewBox={`0 0 ${n} ${n}`} width={size} height={size} role=\"img\" aria-label=\"Código QR de cobro (ilustración)\" className=\"rounded-lg bg-white p-1.5\">\n      {finder(0, 0)}\n      {finder(n - 7, 0)}\n      {finder(0, n - 7)}\n      {cells.map(([x, y]) => (\n        <rect key={`${x}-${y}`} x={x} y={y} width=\"1\" height=\"1\" fill=\"#050B12\" />\n      ))}\n    </svg>\n  );\n}\n",
 "components/landing/Faq.tsx": "\"use client\";\n\nimport { useState } from \"react\";\n\nexport function Faq({ items }: { items: { q: string; a: string }[] }) {\n  const [open, setOpen] = useState<number | null>(0);\n  return (\n    <div className=\"mx-auto max-w-3xl space-y-3\">\n      {items.map((it, i) => {\n        const isOpen = open === i;\n        return (\n          <div key={it.q} className=\"rounded-xl border border-white/10 bg-[#0A131D]\">\n            <button\n              type=\"button\"\n              aria-expanded={isOpen}\n              onClick={() => setOpen(isOpen ? null : i)}\n              className=\"flex w-full items-center justify-between gap-4 p-4 text-left font-semibold\"\n            >\n              {it.q}\n              <span className={`text-xl text-[#00D6A0] transition-transform duration-300 ${isOpen ? \"rotate-45\" : \"\"}`}>+</span>\n            </button>\n            <div className={`grid transition-all duration-300 ${isOpen ? \"grid-rows-[1fr]\" : \"grid-rows-[0fr]\"}`}>\n              <div className=\"overflow-hidden\">\n                <p className=\"px-4 pb-4 text-sm leading-relaxed text-[#A7B4C3]\">{it.a}</p>\n              </div>\n            </div>\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
 "components/landing/HeroMockup.tsx": "import { QrArt } from \"./QrArt\";\n\nexport function HeroMockup() {\n  return (\n    <div className=\"relative mx-auto w-full max-w-xl\">\n      <div className=\"absolute -inset-6 rounded-[2rem] bg-[#00D6A0]/10 blur-3xl\" aria-hidden />\n      <div className=\"relative rounded-2xl border border-white/10 bg-[#0A131D] p-4 shadow-2xl\">\n        <div className=\"mb-3 flex items-center justify-between\">\n          <div className=\"flex gap-1.5\">\n            <span className=\"h-2.5 w-2.5 rounded-full bg-white/20\" />\n            <span className=\"h-2.5 w-2.5 rounded-full bg-white/20\" />\n            <span className=\"h-2.5 w-2.5 rounded-full bg-white/20\" />\n          </div>\n          <span className=\"rounded-full bg-[#00D6A0]/15 px-2.5 py-1 text-xs text-[#00D6A0]\">Caja 1 · activa</span>\n        </div>\n\n        <div className=\"rounded-xl border border-[#00D6A0]/40 bg-[#00D6A0]/10 p-4\">\n          <p className=\"text-xs text-[#A7B4C3]\">Pago acreditado</p>\n          <p className=\"mt-1 text-3xl font-extrabold text-white\">$ 48.500,00</p>\n          <p className=\"mt-1 text-sm text-[#A7B4C3]\">Carlos Benítez · Op. 928374650192</p>\n          <div className=\"mt-3 flex flex-wrap gap-2 text-xs\">\n            <span className=\"rounded-full bg-[#00D6A0] px-2.5 py-1 font-semibold text-[#050B12]\">✓ Verificado</span>\n            <span className=\"rounded-full border border-white/15 px-2.5 py-1 text-white\">Comprobante único</span>\n          </div>\n        </div>\n\n        <div className=\"mt-3 grid grid-cols-5 gap-3\">\n          <div className=\"col-span-3 space-y-2\">\n            <div className=\"rounded-xl border border-white/10 p-3\">\n              <p className=\"text-xs text-[#A7B4C3]\">Estado de operación</p>\n              <div className=\"mt-2 flex items-center gap-1.5 text-[10px] text-[#A7B4C3]\">\n                <span className=\"rounded bg-[#00D6A0] px-1.5 py-0.5 font-semibold text-[#050B12]\">Recibido</span>\n                <span className=\"h-px flex-1 bg-[#00D6A0]\" />\n                <span className=\"rounded bg-[#00D6A0] px-1.5 py-0.5 font-semibold text-[#050B12]\">Acreditado</span>\n                <span className=\"h-px flex-1 bg-white/20\" />\n                <span className=\"rounded border border-white/20 px-1.5 py-0.5\">Entregado</span>\n              </div>\n            </div>\n            <div className=\"rounded-xl border border-white/10 p-3\">\n              <p className=\"text-xs text-[#A7B4C3]\">Seguridad</p>\n              <p className=\"mt-1 text-sm text-white\">Reuso de comprobante: <span className=\"text-[#00D6A0]\">bloqueado</span></p>\n            </div>\n          </div>\n          <div className=\"col-span-2 flex flex-col items-center justify-center rounded-xl border border-white/10 p-3\">\n            <QrArt size={84} />\n            <p className=\"mt-2 text-center text-[10px] text-[#A7B4C3]\">QR de cobro</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
 "components/landing/Navbar.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { useState } from \"react\";\nimport { Logo } from \"./Logo\";\n\nconst LINKS = [\n  [\"Cómo funciona\", \"#como-funciona\"],\n  [\"Funciones\", \"#funciones\"],\n  [\"QR y cajas\", \"#qr-cajas\"],\n  [\"Planes\", \"#planes\"],\n  [\"Preguntas frecuentes\", \"#faq\"],\n];\n\nexport function Navbar() {\n  const [open, setOpen] = useState(false);\n  const close = () => setOpen(false);\n\n  return (\n    <header className=\"sticky top-0 z-50 border-b border-white/10 bg-[#050B12]/70 backdrop-blur-md\">\n      <nav className=\"mx-auto flex max-w-7xl items-center justify-between px-4 py-3\">\n        <Link href=\"/\" aria-label=\"ARCREDIX inicio\" onClick={close}>\n          <Logo />\n        </Link>\n\n        <ul className=\"hidden items-center gap-7 text-sm text-[#A7B4C3] lg:flex\">\n          {LINKS.map(([label, href]) => (\n            <li key={href}>\n              <a href={href} className=\"transition-colors hover:text-white\">{label}</a>\n            </li>\n          ))}\n        </ul>\n\n        <div className=\"hidden items-center gap-3 lg:flex\">\n          <Link href=\"/login\" className=\"rounded-lg border border-white/20 px-4 py-2 text-sm text-white transition-colors hover:border-white/40\">\n            Ingresar\n          </Link>\n          <a href=\"#planes\" className=\"rounded-lg bg-[#00D6A0] px-4 py-2 text-sm font-semibold text-[#050B12] transition-colors hover:bg-[#20E6C0]\">\n            Ver planes\n          </a>\n        </div>\n\n        <button\n          type=\"button\"\n          aria-label=\"Abrir menú\"\n          aria-expanded={open}\n          onClick={() => setOpen((v) => !v)}\n          className=\"rounded-lg border border-white/20 p-2 lg:hidden\"\n        >\n          <span className=\"block h-0.5 w-5 bg-white\" />\n          <span className=\"mt-1 block h-0.5 w-5 bg-white\" />\n          <span className=\"mt-1 block h-0.5 w-5 bg-white\" />\n        </button>\n      </nav>\n\n      {open && (\n        <div className=\"border-t border-white/10 bg-[#050B12]/95 px-4 pb-5 lg:hidden\">\n          <ul className=\"space-y-1 py-3 text-[#A7B4C3]\">\n            {LINKS.map(([label, href]) => (\n              <li key={href}>\n                <a href={href} onClick={close} className=\"block rounded-lg px-2 py-2.5 hover:bg-white/5 hover:text-white\">{label}</a>\n              </li>\n            ))}\n          </ul>\n          <div className=\"flex gap-3\">\n            <Link href=\"/login\" onClick={close} className=\"flex-1 rounded-lg border border-white/20 px-4 py-2.5 text-center text-white\">Ingresar</Link>\n            <a href=\"#planes\" onClick={close} className=\"flex-1 rounded-lg bg-[#00D6A0] px-4 py-2.5 text-center font-semibold text-[#050B12]\">Ver planes</a>\n          </div>\n        </div>\n      )}\n    </header>\n  );\n}\n",
 "components/landing/LiveDemo.tsx": "\"use client\";\n\nimport { useRef, useState } from \"react\";\nimport { QrArt } from \"./QrArt\";\n\ntype Op = { id: number; code: string; amount: number; who: string; status: \"ACREDITADO\" | \"VALIDADO\" };\ntype Result = { kind: \"ok\" | \"used\" | \"missing\" | \"empty\"; text: string };\n\nconst SAMPLES = [\n  { amount: 15000, who: \"María González\" },\n  { amount: 48500, who: \"Carlos Benítez\" },\n  { amount: 7250.5, who: \"Lucía Fernández\" },\n  { amount: 126000, who: \"Distribuidora Del Sur\" },\n];\n\nconst money = (n: number) => n.toLocaleString(\"es-AR\", { style: \"currency\", currency: \"ARS\" });\nconst fakeCode = () => String(Math.floor(900000000000 + Math.random() * 99999999999));\n\nfunction speak(op: Op) {\n  if (typeof window === \"undefined\" || !(\"speechSynthesis\" in window)) return;\n  const pesos = Math.floor(op.amount);\n  const cents = Math.round((op.amount - pesos) * 100);\n  const text = `Ingresó una transferencia de ${pesos.toLocaleString(\"es-AR\")} pesos${cents ? ` con ${cents} centavos` : \"\"} de ${op.who}`;\n  const u = new SpeechSynthesisUtterance(text);\n  u.lang = \"es-AR\";\n  window.speechSynthesis.cancel();\n  window.speechSynthesis.speak(u);\n}\n\nexport function LiveDemo() {\n  const [ops, setOps] = useState<Op[]>([]);\n  const [voice, setVoice] = useState(false);\n  const [code, setCode] = useState(\"\");\n  const [result, setResult] = useState<Result | null>(null);\n  const counter = useRef(0);\n\n  function simulate() {\n    const s = SAMPLES[counter.current % SAMPLES.length];\n    counter.current += 1;\n    const op: Op = { id: counter.current, code: fakeCode(), amount: s.amount, who: s.who, status: \"ACREDITADO\" };\n    setOps((o) => [op, ...o].slice(0, 4));\n    setResult(null);\n    if (voice) speak(op);\n  }\n\n  function validate(id: number) {\n    setOps((o) => o.map((x) => (x.id === id ? { ...x, status: \"VALIDADO\" } : x)));\n  }\n\n  function check() {\n    const c = code.trim();\n    if (c.length < 6) return setResult({ kind: \"empty\", text: \"Ingresá un número de operación.\" });\n    const op = ops.find((x) => x.code === c);\n    if (!op) return setResult({ kind: \"missing\", text: \"NO ENCONTRADO: ese pago no figura en tu cuenta. No entregues.\" });\n    if (op.status === \"VALIDADO\") return setResult({ kind: \"used\", text: \"COMPROBANTE YA USADO. No entregues.\" });\n    setResult({ kind: \"ok\", text: `ACREDITADO: ${money(op.amount)} de ${op.who}. Podés validar y entregar.` });\n  }\n\n  const tone = (k: Result[\"kind\"]) =>\n    k === \"ok\" ? \"bg-[#00D6A0]/15 text-[#00D6A0]\" : k === \"empty\" ? \"bg-white/10 text-[#A7B4C3]\" : \"bg-red-500/15 text-red-300\";\n\n  return (\n    <div className=\"grid gap-5 lg:grid-cols-5\">\n      <div className=\"rounded-2xl border border-white/10 bg-[#0A131D] p-5 lg:col-span-3\">\n        <div className=\"flex flex-wrap items-center justify-between gap-3\">\n          <h3 className=\"font-semibold\">Caja · ingresos en vivo</h3>\n          <label className=\"flex cursor-pointer items-center gap-2 text-sm text-[#A7B4C3]\">\n            <input type=\"checkbox\" checked={voice} onChange={(e) => setVoice(e.target.checked)} className=\"accent-[#00D6A0]\" />\n            Aviso por voz\n          </label>\n        </div>\n\n        <button onClick={simulate} className=\"mt-4 w-full rounded-lg bg-[#00D6A0] px-4 py-3 font-semibold text-[#050B12] transition-colors hover:bg-[#20E6C0]\">\n          Simular una transferencia entrante\n        </button>\n\n        <div className=\"mt-4 space-y-3\">\n          {ops.length === 0 && <p className=\"py-6 text-center text-sm text-[#A7B4C3]\">Esperando transferencias... tocá el botón de arriba.</p>}\n          {ops.map((o) => (\n            <div key={o.id} className={`flex items-center justify-between gap-3 rounded-xl border p-4 ${o.status === \"ACREDITADO\" ? \"border-[#00D6A0]/50 bg-[#00D6A0]/10\" : \"border-white/10 bg-white/5 opacity-70\"}`}>\n              <div>\n                <p className=\"text-xl font-bold\">{money(o.amount)}</p>\n                <p className=\"text-sm text-[#A7B4C3]\">{o.who}</p>\n                <p className=\"font-mono text-xs text-[#A7B4C3]/70\">Op. {o.code}</p>\n              </div>\n              {o.status === \"ACREDITADO\" ? (\n                <button onClick={() => validate(o.id)} className=\"shrink-0 rounded-lg bg-[#00D6A0] px-3 py-2 text-sm font-semibold text-[#050B12] hover:bg-[#20E6C0]\">\n                  Validar y entregar\n                </button>\n              ) : (\n                <span className=\"shrink-0 rounded-full border border-white/20 px-3 py-1 text-xs text-[#A7B4C3]\">Validado</span>\n              )}\n            </div>\n          ))}\n        </div>\n      </div>\n\n      <div className=\"space-y-5 lg:col-span-2\">\n        <div className=\"rounded-2xl border border-white/10 bg-[#0A131D] p-5\">\n          <h3 className=\"font-semibold\">Verificar un comprobante</h3>\n          <p className=\"mt-1 text-xs text-[#A7B4C3]\">Pegá el número de operación que te muestra el cliente.</p>\n          <div className=\"mt-3 flex gap-2\">\n            <input value={code} onChange={(e) => setCode(e.target.value)} placeholder=\"N° de operación\" inputMode=\"numeric\"\n              className=\"min-w-0 flex-1 rounded-lg border border-white/15 bg-white/5 px-3 py-2 font-mono text-sm outline-none focus:border-[#00D6A0]\" />\n            <button onClick={check} className=\"rounded-lg border border-[#00D6A0] px-3 text-sm text-[#00D6A0] hover:bg-[#00D6A0]/10\">Verificar</button>\n          </div>\n          <div className=\"mt-2 flex flex-wrap gap-2 text-xs\">\n            <button onClick={() => ops[0] && setCode(ops[0].code)} className=\"rounded-full border border-white/15 px-2.5 py-1 text-[#A7B4C3] hover:text-white\">Usar el último cobro</button>\n            <button onClick={() => setCode(fakeCode())} className=\"rounded-full border border-white/15 px-2.5 py-1 text-[#A7B4C3] hover:text-white\">Probar uno inventado</button>\n          </div>\n          {result && <p className={`mt-3 rounded-lg p-3 text-sm font-semibold ${tone(result.kind)}`}>{result.text}</p>}\n        </div>\n\n        <div className=\"flex items-center gap-4 rounded-2xl border border-white/10 bg-[#0A131D] p-5\">\n          <QrArt size={84} />\n          <div>\n            <h3 className=\"font-semibold\">QR de cobro</h3>\n            <p className=\"mt-1 text-xs text-[#A7B4C3]\">Ilustración de cómo se vería el QR del punto de venta.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
 "components/landing/Logo.tsx": "import Image from \"next/image\";\n\nexport function Logo({ size = 34 }: { size?: number }) {\n  return (\n    <span className=\"inline-flex items-center gap-2\">\n      <Image src=\"/arcredix-isotipo.png\" alt=\"\" width={size} height={size} priority />\n      <span className=\"text-xl font-extrabold italic tracking-tight text-white\">\n        ARCREDI<span className=\"text-[#00D6A0]\">X</span>\n      </span>\n    </span>\n  );\n}\n",
 "components/landing/Reveal.tsx": "\"use client\";\n\nimport { useEffect, useRef, useState, type ReactNode } from \"react\";\n\n/** Aparición progresiva al hacer scroll (respeta \"reducir movimiento\"). */\nexport function Reveal({ children, delay = 0, className = \"\" }: { children: ReactNode; delay?: number; className?: string }) {\n  const ref = useRef<HTMLDivElement>(null);\n  const [shown, setShown] = useState(false);\n\n  useEffect(() => {\n    const el = ref.current;\n    if (!el) return;\n    if (window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) {\n      setShown(true);\n      return;\n    }\n    const io = new IntersectionObserver(\n      ([e]) => {\n        if (e.isIntersecting) {\n          setShown(true);\n          io.disconnect();\n        }\n      },\n      { threshold: 0.12 },\n    );\n    io.observe(el);\n    return () => io.disconnect();\n  }, []);\n\n  return (\n    <div\n      ref={ref}\n      style={{ transitionDelay: `${delay}ms` }}\n      className={`transition-all duration-700 ease-out ${shown ? \"translate-y-0 opacity-100\" : \"translate-y-6 opacity-0\"} ${className}`}\n    >\n      {children}\n    </div>\n  );\n}\n",
 "app/page.tsx": "import Link from \"next/link\";\nimport { PLANS } from \"@/lib/plans\";\nimport { buyLink } from \"@/lib/config\";\nimport { Navbar } from \"@/components/landing/Navbar\";\nimport { Logo } from \"@/components/landing/Logo\";\nimport { Reveal } from \"@/components/landing/Reveal\";\nimport { HeroMockup } from \"@/components/landing/HeroMockup\";\nimport { LiveDemo } from \"@/components/landing/LiveDemo\";\nimport { Faq } from \"@/components/landing/Faq\";\n\nconst G = \"text-[#00D6A0]\";\nconst card =\n  \"rounded-2xl border border-white/10 bg-[#0A131D] p-6 transition-all duration-300 hover:border-[#00D6A0]/40 hover:shadow-[0_0_40px_-12px_rgba(0,214,160,0.45)]\";\nconst h2 = \"text-3xl font-extrabold sm:text-4xl\";\n\nconst PROBLEMS = [\n  [\"Comprobantes falsos\", \"Capturas editadas que parecen reales y se entregan sin que el dinero haya entrado.\"],\n  [\"Pagos pendientes o inexistentes\", \"El cliente muestra una transferencia que todavía no se acreditó o que nunca existió.\"],\n  [\"Errores al verificar transferencias\", \"Revisar la app del banco en plena venta lleva a confundir montos, nombres o fechas.\"],\n  [\"Pérdida de tiempo en controles manuales\", \"Cada verificación detiene la fila y distrae a quien atiende.\"],\n];\n\nconst STEPS = [\n  [\"El comercio recibe una operación\", \"El cliente transfiere al alias o CVU del local.\"],\n  [\"Se verifica la información del cobro\", \"ARCREDIX toma la confirmación de tu banco o billetera, no la captura del cliente.\"],\n  [\"ARCREDIX permite consultar el estado\", \"En caja ves el cobro al instante, con aviso por voz, o lo buscás por número de operación.\"],\n  [\"El comercio decide con mayor seguridad\", \"Al validar y entregar, el comprobante queda usado y no puede repetirse.\"],\n];\n\nconst FEATURES = [\n  [\"Validación de cobros\", \"Cada transferencia se confirma contra la fuente real y queda registrada como disponible o validada.\", false],\n  [\"QR de operaciones\", \"Un código QR para el punto de cobro de tu comercio.\", true],\n  [\"Gestión de cajas\", \"Cada cajero entra con su PIN y ve solo lo que necesita para cobrar.\", false],\n  [\"Control de comercios\", \"Altas, planes, vencimientos y suspensión desde un panel central.\", false],\n  [\"Usuarios y permisos\", \"Dueño y cajeros con permisos distintos: sin saldos ni reportes en el mostrador.\", false],\n  [\"Historial de operaciones\", \"Todos tus comprobantes en un lugar, exportables a Excel.\", false],\n  [\"Integraciones con proveedores de pago\", \"Mercado Pago y notificaciones por correo de tu banco.\", false],\n  [\"Panel de administración\", \"Métricas y control de todos los comercios en un solo lugar.\", false],\n] as const;\n\nconst PLAN_UI = {\n  starter: {\n    desc: \"Para comercios con una sola caja.\",\n    features: [\"1 usuario dueño + 1 vista de caja\", \"1 billetera o banco vinculado\", \"Aviso automático por voz en vivo\", \"Bloqueo anti-doble uso\", \"Historial de 30 días\"],\n  },\n  pro: {\n    desc: \"Para comercios con varios puntos de cobro.\",\n    features: [\"Dueño + hasta 4 cajas con PIN\", \"Hasta 3 bancos, billeteras o alias\", \"Historial ilimitado y exportación a Excel\", \"Escáner de comprobantes por cámara (próximamente)\"],\n  },\n  enterprise: {\n    desc: \"Para distribuidoras, corralones y cadenas con sucursales.\",\n    features: [\"Cajas y usuarios ilimitados\", \"Múltiples sucursales y cuentas\", \"Alertas de anomalías y auditoría por cajero\", \"Soporte prioritario por WhatsApp\"],\n  },\n} as const;\n\nconst FAQ = [\n  { q: \"¿Qué es ARCREDIX?\", a: \"Es una plataforma para validar los cobros de tu comercio, prevenir estafas con comprobantes falsos y controlar las operaciones desde un solo lugar.\" },\n  { q: \"¿Cómo funciona la validación?\", a: \"ARCREDIX no se basa en la captura del cliente: registra la confirmación real que emite tu banco o billetera. En caja ves el cobro con aviso por voz y, al validarlo, ese comprobante queda usado y no puede repetirse.\" },\n  { q: \"¿Cómo contrato un plan?\", a: \"Elegí tu plan en esta página y escribinos desde el botón de contratación. Damos de alta tu comercio y te enviamos tus accesos.\" },\n  { q: \"¿Qué necesita mi comercio para empezar?\", a: \"Una cuenta que reciba transferencias (alias o CVU), acceso a las notificaciones de esa cuenta (Mercado Pago o correos de tu banco) y un dispositivo con navegador en la caja. La compatibilidad con cada banco depende de las notificaciones que envíe; la verificamos con vos al comenzar.\" },\n  { q: \"¿Cómo ingreso a la plataforma?\", a: \"Los dueños ingresan desde el botón “Ingresar” con su email y contraseña. Los cajeros entran a la caja con el código de su comercio y su PIN de 4 dígitos.\" },\n  { q: \"¿Qué incluye cada plan?\", a: \"Starter cubre una caja y una cuenta. Comercio Pro suma hasta 4 cajas, 3 cuentas e historial ilimitado. Empresa no tiene límite de cajas, cuentas ni sucursales. Mirá el detalle en la sección Planes.\" },\n];\n\nexport default function Home() {\n  return (\n    <>\n      <Navbar />\n\n      {/* 1. HERO */}\n      <section className=\"relative overflow-hidden\">\n        <div className=\"pointer-events-none absolute inset-0\" style={{ background: \"radial-gradient(55% 50% at 72% 35%, rgba(0,214,160,0.16), transparent 70%)\" }} aria-hidden />\n        <div className=\"relative mx-auto grid max-w-7xl items-center gap-12 px-4 py-16 lg:grid-cols-2 lg:py-24\">\n          <div>\n            <h1 className=\"text-4xl font-extrabold leading-tight sm:text-5xl lg:text-6xl\">\n              No entregues tu producto <span className=\"bg-gradient-to-r from-[#00D6A0] to-[#20E6C0] bg-clip-text text-transparent\">sin confirmar tu dinero.</span>\n            </h1>\n            <p className=\"mt-6 max-w-xl text-lg text-[#A7B4C3]\">\n              ARCREDIX te ayuda a validar tus cobros, prevenir estafas y controlar las operaciones de tu comercio desde un solo lugar.\n            </p>\n            <div className=\"mt-8 flex flex-col gap-3 sm:flex-row\">\n              <a href=\"#como-funciona\" className=\"rounded-lg bg-[#00D6A0] px-6 py-3 text-center font-semibold text-[#050B12] transition-colors hover:bg-[#20E6C0]\">Ver cómo funciona</a>\n              <a href=\"#planes\" className=\"rounded-lg border border-white/20 px-6 py-3 text-center transition-colors hover:border-white/40\">Conocer los planes</a>\n            </div>\n          </div>\n          <HeroMockup />\n        </div>\n      </section>\n\n      {/* 2. EL PROBLEMA */}\n      <section id=\"problema\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} text-center`}>Una captura <span className={G}>no confirma</span> un pago.</h2>\n          <p className=\"mx-auto mt-4 max-w-2xl text-center text-[#A7B4C3]\">\n            Confiar únicamente en el comprobante que te muestra el cliente deja a tu comercio expuesto a estos riesgos.\n          </p>\n        </Reveal>\n        <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4\">\n          {PROBLEMS.map(([t, d], i) => (\n            <Reveal key={t} delay={i * 80}>\n              <div className={`${card} h-full`}>\n                <span className=\"mb-3 inline-flex h-9 w-9 items-center justify-center rounded-lg bg-red-500/10 text-red-300\">!</span>\n                <h3 className=\"font-semibold\">{t}</h3>\n                <p className=\"mt-2 text-sm text-[#A7B4C3]\">{d}</p>\n              </div>\n            </Reveal>\n          ))}\n        </div>\n      </section>\n\n      {/* 3. LA SOLUCIÓN */}\n      <section id=\"como-funciona\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} text-center`}>Validá. Confirmá. <span className={G}>Entregá.</span></h2>\n          <p className=\"mx-auto mt-4 max-w-2xl text-center text-[#A7B4C3]\">ARCREDIX pone la confirmación real del dinero a un toque de distancia del mostrador.</p>\n        </Reveal>\n        <div className=\"relative mt-12 grid gap-4 lg:grid-cols-4\">\n          <div className=\"pointer-events-none absolute left-[12%] right-[12%] top-[34px] hidden h-px bg-gradient-to-r from-[#00D6A0]/0 via-[#00D6A0]/60 to-[#00D6A0]/0 lg:block\" aria-hidden />\n          {STEPS.map(([t, d], i) => (\n            <Reveal key={t} delay={i * 100}>\n              <div className={`${card} relative h-full text-center`}>\n                <span className=\"mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-gradient-to-br from-[#00D6A0] to-[#20E6C0] text-lg font-extrabold text-[#050B12]\">{i + 1}</span>\n                <h3 className=\"font-semibold\">{t}</h3>\n                <p className=\"mt-2 text-sm text-[#A7B4C3]\">{d}</p>\n              </div>\n            </Reveal>\n          ))}\n        </div>\n      </section>\n\n      {/* 4. DEMOSTRACIÓN INTERACTIVA */}\n      <section id=\"qr-cajas\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} text-center`}>Conocé ARCREDIX <span className={G}>en acción.</span></h2>\n          <p className=\"mx-auto mt-4 max-w-2xl text-center text-[#A7B4C3]\">Probá cómo se ve un cobro en caja: simulá una transferencia, validala y verificá un comprobante repetido o falso. Sin registrarte.</p>\n        </Reveal>\n        <Reveal className=\"mt-10\">\n          <LiveDemo />\n        </Reveal>\n      </section>\n\n      {/* 5. FUNCIONALIDADES */}\n      <section id=\"funciones\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} text-center`}>Todo el control de <span className={G}>tus cobros.</span></h2>\n        </Reveal>\n        <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4\">\n          {FEATURES.map(([t, d, soon], i) => (\n            <Reveal key={t} delay={(i % 4) * 70}>\n              <div className={`${card} h-full`}>\n                <div className=\"mb-3 flex items-center justify-between\">\n                  <span className=\"inline-flex h-9 w-9 items-center justify-center rounded-lg bg-[#00D6A0]/10 text-[#00D6A0]\">✓</span>\n                  {soon && <span className=\"rounded-full border border-white/15 px-2 py-0.5 text-[10px] uppercase tracking-wide text-[#A7B4C3]\">Próximamente</span>}\n                </div>\n                <h3 className=\"font-semibold\">{t}</h3>\n                <p className=\"mt-2 text-sm text-[#A7B4C3]\">{d}</p>\n              </div>\n            </Reveal>\n          ))}\n        </div>\n      </section>\n\n      {/* 6. PLANES */}\n      <section id=\"planes\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} text-center`}>Un plan para cada etapa de <span className={G}>tu comercio.</span></h2>\n          <p className=\"mt-3 text-center text-sm text-[#A7B4C3]\">Valores en dólares estadounidenses (USD).</p>\n        </Reveal>\n        <div className=\"mt-10 grid gap-5 lg:grid-cols-3\">\n          {([\"starter\", \"pro\", \"enterprise\"] as const).map((id, i) => {\n            const p = PLANS[id];\n            const ui = PLAN_UI[id];\n            const featured = id === \"pro\";\n            return (\n              <Reveal key={id} delay={i * 100}>\n                <div className={`flex h-full flex-col rounded-2xl border p-6 ${featured ? \"border-[#00D6A0] bg-[#00D6A0]/[0.06] shadow-[0_0_50px_-15px_rgba(0,214,160,0.5)]\" : \"border-white/10 bg-[#0A131D]\"}`}>\n                  {featured && <span className={`mb-2 text-xs font-bold uppercase tracking-wide ${G}`}>Más vendido</span>}\n                  <h3 className=\"text-xl font-bold\">{p.name}</h3>\n                  <p className=\"mt-1 text-sm text-[#A7B4C3]\">{ui.desc}</p>\n                  <p className=\"mt-5 text-4xl font-extrabold\">USD {p.priceMonthly}<span className=\"text-base font-normal text-[#A7B4C3]\"> / mes</span></p>\n                  <p className=\"text-sm text-[#A7B4C3]\">Abono mensual · setup único opcional de USD {p.setup}</p>\n                  <ul className=\"mt-5 flex-1 space-y-2 text-sm\">\n                    {ui.features.map((f) => (\n                      <li key={f} className=\"flex gap-2\"><span className={G}>✓</span><span className=\"text-[#E6ECF2]\">{f}</span></li>\n                    ))}\n                  </ul>\n                  <a href={buyLink(p.name)} className={`mt-6 rounded-lg px-4 py-3 text-center font-semibold transition-colors ${featured ? \"bg-[#00D6A0] text-[#050B12] hover:bg-[#20E6C0]\" : \"border border-white/20 hover:border-white/40\"}`}>\n                    Contratar\n                  </a>\n                </div>\n              </Reveal>\n            );\n          })}\n        </div>\n      </section>\n\n      {/* 7. LICENCIA PROPIA */}\n      <section className=\"mx-auto max-w-7xl px-4 py-20\">\n        <Reveal>\n          <div className=\"rounded-3xl border border-[#00D6A0]/30 bg-gradient-to-br from-[#00D6A0]/10 to-transparent p-8 sm:p-12\">\n            <h2 className={h2}>Tu comercio. Tu cuenta. <span className={G}>Tu control.</span></h2>\n            <p className=\"mt-4 max-w-2xl text-[#A7B4C3]\">ARCREDIX cuenta con un sistema de licencias y acceso para cada comercio.</p>\n            <ul className=\"mt-6 grid gap-3 text-sm sm:grid-cols-2 lg:grid-cols-3\">\n              {[\"Acceso individual por comercio\", \"Gestión de vigencia\", \"Administración centralizada\", \"Control de usuarios\", \"Acceso seguro al portal\"].map((t) => (\n                <li key={t} className=\"flex items-center gap-2\"><span className={G}>✓</span>{t}</li>\n              ))}\n            </ul>\n            <p className=\"mt-6 text-sm text-[#A7B4C3]\">\n              ¿Preferís no pagar abonos mensuales? Consultá por la <strong className=\"text-white\">Licencia Propia</strong> (pago único de USD {PLANS.lifetime.setup}).\n            </p>\n            <a href={buyLink(PLANS.lifetime.name)} className=\"mt-5 inline-block rounded-lg border border-[#00D6A0] px-5 py-2.5 text-sm font-semibold text-[#00D6A0] transition-colors hover:bg-[#00D6A0]/10\">Consultar por la licencia</a>\n          </div>\n        </Reveal>\n      </section>\n\n      {/* 8. FAQ */}\n      <section id=\"faq\" className=\"mx-auto max-w-7xl scroll-mt-20 px-4 py-20\">\n        <Reveal>\n          <h2 className={`${h2} mb-10 text-center`}>Preguntas frecuentes.</h2>\n        </Reveal>\n        <Faq items={FAQ} />\n      </section>\n\n      {/* 9. CTA FINAL */}\n      <section className=\"px-4 py-20\">\n        <Reveal>\n          <div className=\"mx-auto max-w-4xl rounded-3xl border border-white/10 p-10 text-center\" style={{ background: \"radial-gradient(70% 120% at 50% 0%, rgba(0,214,160,0.14), rgba(32,230,192,0.04) 55%, transparent)\" }}>\n            <h2 className={h2}>Protegé tus operaciones desde hoy.</h2>\n            <p className=\"mx-auto mt-4 max-w-xl text-[#A7B4C3]\">Empezá a mejorar el control de tus cobros con ARCREDIX.</p>\n            <a href=\"#planes\" className=\"mt-8 inline-block rounded-lg bg-[#00D6A0] px-8 py-3 font-semibold text-[#050B12] transition-colors hover:bg-[#20E6C0]\">Ver planes</a>\n          </div>\n        </Reveal>\n      </section>\n\n      {/* 10. FOOTER */}\n      <footer className=\"border-t border-white/10 px-4 py-12\">\n        <div className=\"mx-auto grid max-w-7xl gap-8 md:grid-cols-3\">\n          <div>\n            <Logo />\n            <p className=\"mt-3 text-sm text-[#A7B4C3]\">Validá tus cobros. Evitá estafas.</p>\n          </div>\n          <nav aria-label=\"Enlaces\" className=\"grid grid-cols-2 gap-2 text-sm text-[#A7B4C3]\">\n            <Link href=\"/\" className=\"hover:text-white\">Inicio</Link>\n            <a href=\"#como-funciona\" className=\"hover:text-white\">Cómo funciona</a>\n            <a href=\"#funciones\" className=\"hover:text-white\">Funciones</a>\n            <a href=\"#planes\" className=\"hover:text-white\">Planes</a>\n            <a href=\"#faq\" className=\"hover:text-white\">Preguntas frecuentes</a>\n            <Link href=\"/login\" className=\"hover:text-white\">Ingresar</Link>\n          </nav>\n          <div className=\"space-y-2 text-sm text-[#A7B4C3]\">\n            <Link href=\"/terminos\" className=\"block hover:text-white\">Términos y condiciones</Link>\n            <Link href=\"/privacidad\" className=\"block hover:text-white\">Política de privacidad</Link>\n          </div>\n        </div>\n        <p className=\"mx-auto mt-10 max-w-7xl text-center text-xs text-[#A7B4C3]/70\">ARCREDIX. Todos los derechos reservados.</p>\n      </footer>\n    </>\n  );\n}\n",
 "app/layout.tsx": "import type { Metadata } from \"next\";\nimport { Sora } from \"next/font/google\";\nimport \"./globals.css\";\n\nconst sora = Sora({ subsets: [\"latin\"], weight: [\"400\", \"500\", \"600\", \"700\", \"800\"], display: \"swap\" });\n\nexport const metadata: Metadata = {\n  title: \"ARCREDIX | Validá tus cobros. Evitá estafas.\",\n  description:\n    \"ARCREDIX te ayuda a validar tus cobros, prevenir estafas y controlar las operaciones de tu comercio desde un solo lugar.\",\n};\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"es\" className=\"scroll-smooth\">\n      <body>\n        <div className={`${sora.className} min-h-screen bg-[#050B12] text-white antialiased`}>{children}</div>\n      </body>\n    </html>\n  );\n}\n",
 "app/terminos/page.tsx": "import Link from \"next/link\";\nimport { Logo } from \"@/components/landing/Logo\";\n\nexport const metadata = { title: \"Términos y condiciones | ARCREDIX\" };\n\nexport default function Page() {\n  return (\n    <main className=\"mx-auto max-w-3xl px-4 py-16\">\n      <Link href=\"/\" aria-label=\"Volver al inicio\"><Logo /></Link>\n      <h1 className=\"mt-10 text-3xl font-extrabold\">Términos y condiciones</h1>\n      <p className=\"mt-6 rounded-xl border border-white/10 bg-[#0A131D] p-5 text-[#A7B4C3]\">\n        Este documento está en preparación. Reemplazá este texto por el contenido legal definitivo de ARCREDIX\n        (conviene que lo revise un profesional antes de publicarlo).\n      </p>\n      <Link href=\"/\" className=\"mt-8 inline-block text-[#00D6A0] underline\">Volver al inicio</Link>\n    </main>\n  );\n}\n",
 "app/privacidad/page.tsx": "import Link from \"next/link\";\nimport { Logo } from \"@/components/landing/Logo\";\n\nexport const metadata = { title: \"Política de privacidad | ARCREDIX\" };\n\nexport default function Page() {\n  return (\n    <main className=\"mx-auto max-w-3xl px-4 py-16\">\n      <Link href=\"/\" aria-label=\"Volver al inicio\"><Logo /></Link>\n      <h1 className=\"mt-10 text-3xl font-extrabold\">Política de privacidad</h1>\n      <p className=\"mt-6 rounded-xl border border-white/10 bg-[#0A131D] p-5 text-[#A7B4C3]\">\n        Este documento está en preparación. Reemplazá este texto por el contenido legal definitivo de ARCREDIX\n        (conviene que lo revise un profesional antes de publicarlo).\n      </p>\n      <Link href=\"/\" className=\"mt-8 inline-block text-[#00D6A0] underline\">Volver al inicio</Link>\n    </main>\n  );\n}\n"
};

const BIN_FILES = {"public/arcredix-isotipo.png": ""};


function write(rel, content, binary = false) {
  const abs = path.join(root, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  if (binary) fs.writeFileSync(abs, Buffer.from(content, "base64"));
  else fs.writeFileSync(abs, content, "utf8");
  console.log("  [ok] " + rel);
}

console.log("\n1) Escribiendo la nueva landing...");
for (const [rel, c] of Object.entries(TEXT_FILES)) write(rel, c);
for (const [rel, c] of Object.entries(BIN_FILES)) write(rel, c, true);

// 2) Paleta oficial en el resto de la app (dashboard, caja, admin, logins)
console.log("\n2) Unificando colores con la paleta oficial...");
const MAP = [["#00cba6", "#00D6A0"], ["#00070f", "#050B12"]];
let touched = 0;
function walk(dir) {
  for (const name of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, name.name);
    if (name.isDirectory()) walk(p);
    else if (/\.(tsx|ts)$/.test(name.name)) {
      const before = fs.readFileSync(p, "utf8");
      let after = before;
      for (const [a, b] of MAP) after = after.split(a).join(b);
      if (after !== before) {
        fs.writeFileSync(p, after, "utf8");
        touched++;
      }
    }
  }
}
for (const d of ["app", "components"]) if (fs.existsSync(path.join(root, d))) walk(path.join(root, d));
console.log("  [ok] " + touched + " archivos actualizados");

console.log(`
==================== LANDING LISTA ====================
 1. Si el servidor esta corriendo, detenelo (Ctrl + C) y volve a iniciarlo:
      npm run dev
 2. Abri http://localhost:3000
 3. La fuente (Sora) se descarga de Google Fonts: necesitas internet la primera vez.
 4. Los botones "Contratar" abren WhatsApp si completaste NEXT_PUBLIC_WHATSAPP
    en .env.local (formato 5492230000000, sin +). Reinicia el servidor tras cambiarlo.
 5. /terminos y /privacidad tienen texto provisorio: reemplazalo por el legal definitivo.
=======================================================
`);
